<script setup lang="ts">import {ref,onMounted} from 'vue';import {reviews} from '../stores/reviews';import {reports} from '../stores/reports';import {isAdmin} from '../stores/auth';import {request,downloadCsv} from '../api/client';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import StatusPill from '../components/common/StatusPill.vue';import Notice from '../components/common/Notice.vue';import AllocationTable from '../components/AllocationTable.vue';const expanded=ref('');const {error,busy,act}=useTask();onMounted(()=>Promise.all([reviews.load(),reports.load()]));function approve(id:string){act(async()=>{await request('/reviews/'+id+'/approve','POST');await reviews.load()})}function publish(id:string){act(async()=>{await reports.create({review_id:id,title:'档案抽样底册 '+new Date().toLocaleDateString()})})}function download(id:string){act(()=>downloadCsv(id))}</script><template><PageHeading index="05 / 复核归档" title="把抽样依据，与文档清单一起留存。" note="管理员批准后保存不可变快照，下载带具体文档编号、层总体、假设D与检出率的CSV。"/><Notice :message="error"/><div class="two-col"><section><h2>人工复核</h2><article v-for="r in reviews.items.value" :key="r.id" class="review-row"><StatusPill :status="r.state"/><p>{{r.action}}</p><small>{{r.reviewer||'等待管理员核准'}}</small><div v-if="isAdmin()" class="actions"><button v-if="r.state==='submitted'" @click="approve(r.id)" :disabled="busy">批准抽样复核</button><button v-if="r.state==='approved'" class="secondary" @click="publish(r.id)" :disabled="busy">生成归档快照</button></div></article></section><section><h2>已批准底册</h2><article v-for="r in reports.items.value" :key="r.id" class="report-row"><p class="eyebrow">APPROVED SAMPLING REGISTER</p><h3>{{r.title}}</h3><p>{{r.snapshot.manifest.length}}份文档 · 审核人 {{r.snapshot.reviewer}}</p><div class="actions"><button @click="download(r.id)">下载抽样 CSV ↓</button><button class="secondary" @click="expanded=expanded===r.id?'':r.id">查看配额快照</button></div><AllocationTable v-if="expanded===r.id" :rows="r.snapshot.allocation.strata"/></article></section></div></template>
